def correct_illumination(image, blur_kernel=151):
    # The backlight is brighter at the centre; dividing by a heavy Gaussian blur
    # flattens that gradient before thresholding.
    background = cv2.GaussianBlur(image, (blur_kernel, blur_kernel), 0)
    return cv2.divide(image, background, scale=255)

