class RateLimiter:
    """Sliding-window limiter over a pluggable backend: DictBackend for one process, RedisBackend for several workers."""
    def __init__(self, backend):
        self.backend = backend

class RedisBackend:
    def cleanup(self, key):
        items = self.redis.lrange(key, 0, -1)
        self.redis.delete(key)
        self.redis.rpush(key, *fresh(items))

